/**
 * The asynchronous positional-read MaxMind DB reader (src/shadow/mmdb.ts)
 * against databases generated by test/helpers/mmdb-writer.ts: no binary
 * fixture is committed, and every network is a documentation range (misses
 * use non-public addresses). The reader was also checked once, outside CI,
 * against the real IPNetDB prefix file and the reference Python reader
 * (records and prefix lengths identical).
 */
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import { DECODE_MAX_DEPTH, DECODE_MAX_VALUES, MmdbError, MmdbReader, PAGE_CACHE_PAGES } from "../../src/shadow/mmdb.js";
import { buildMmdb, encodeControl, encodePointer, ipnetdbRecord, mmdbType, type MmdbWriteOptions } from "../helpers/mmdb-writer.js";

const dir = mkdtempSync(join(tmpdir(), "mmdb-test-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));
let n = 0;
function write(opts: MmdbWriteOptions): { path: string; build: ReturnType<typeof buildMmdb> } {
  const build = buildMmdb(opts);
  const path = join(dir, `db-${(n += 1)}.mmdb`);
  writeFileSync(path, build.file);
  return { path, build };
}

const NETWORKS: MmdbWriteOptions["networks"] = [
  { network: "192.0.2.0/24", record: ipnetdbRecord({ prefix: "192.0.2.0/24", prefixEntity: "Example Corp Ltd", asEntity: "Example Transit Inc", as: 64496 }) },
  { network: "198.51.100.0/24", record: ipnetdbRecord({ prefix: "198.51.100.0/24", prefixEntity: "Example Hosting LLC", asEntity: "Example Hosting LLC", as: 64497 }) },
  { network: "203.0.113.0/25", record: ipnetdbRecord({ prefix: "203.0.113.0/25", prefixEntity: "Example University", asEntity: "Example Research Network", as: 64498, bogon: true }) },
  { network: "2001:db8::/32", record: ipnetdbRecord({ prefix: "2001:db8::/32", prefixEntity: "Example Corp Ltd", asEntity: "Example Transit Inc", as: 64499 }) },
];

async function withReader<T>(path: string, fn: (r: MmdbReader) => Promise<T>): Promise<T> {
  const r = await MmdbReader.open(path);
  try {
    return await fn(r);
  } finally {
    await r.close();
  }
}

/** A database whose only record (for 192.0.2.0/24) is the hand-made data `blob`, written at data offset 0. */
const hostile = (blob: Buffer) => write({ recordSize: 32, networks: [{ network: "192.0.2.0/24", record: mmdbType.raw(blob) }] }).path;

describe("MmdbReader: lookups", () => {
  it.each([24, 28, 32] as const)("record size %i: IPv4 and IPv6 records with their prefix lengths, not-found addresses", async (recordSize) => {
    const { path } = write({ recordSize, networks: NETWORKS });
    await withReader(path, async (r) => {
      expect(r.metadata).toMatchObject({ recordSize, ipVersion: 6, databaseType: "IPNetDB-Test", binaryFormatMajorVersion: 2, buildEpoch: 1_700_000_000 });
      const a = await r.lookup("192.0.2.77");
      expect(a.prefixLength).toBe(24);
      expect(a.record).toMatchObject({ prefix: "192.0.2.0/24", prefix_entity: "Example Corp Ltd", as_entity: "Example Transit Inc", as: 64496, prefix_bogon: false, prefix_origins: [64496] });
      expect(await r.lookup("198.51.100.1")).toMatchObject({ prefixLength: 24, record: { prefix_entity: "Example Hosting LLC", as: 64497 } });
      expect(await r.lookup("203.0.113.5")).toMatchObject({ prefixLength: 25, record: { prefix_bogon: true, as: 64498 } });
      expect(await r.lookup("2001:db8:1234::1")).toMatchObject({ prefixLength: 32, record: { prefix: "2001:db8::/32", as: 64499 } });
      // Outside every network: the record is null; the prefix length is how far the tree went.
      const miss = await r.lookup("203.0.113.200");
      expect(miss.record).toBeNull();
      expect(miss.prefixLength).toBe(25);
      expect((await r.lookup("10.0.0.1")).record).toBeNull();
      expect((await r.lookup("fd00::1")).record).toBeNull();
      expect((await r.lookup("::1")).record).toBeNull();
    });
  });

  it("decodes every supported data type", async () => {
    const record = {
      text: "Grüße, example",
      flag_true: true,
      flag_false: false,
      u16: mmdbType.uint16(65_535),
      u32: mmdbType.uint32(4_294_967_295),
      u64_small: mmdbType.uint64(42),
      u64_big: mmdbType.uint64(18_446_744_073_709_551_615n),
      u128: mmdbType.uint128(340_282_366_920_938_463_463_374_607_431_768_211_455n),
      i32_neg: mmdbType.int32(-12_345),
      i32_pos: mmdbType.int32(12_345),
      dbl: mmdbType.double(51.5),
      flt: mmdbType.float(1.5),
      raw: Buffer.from([1, 2, 3, 250]),
      list: ["a", mmdbType.uint16(7), { nested: [true] }],
      long_text: "x".repeat(300),
      longer_text: "y".repeat(70_000),
      zero: mmdbType.uint32(0),
    };
    const { path } = write({ networks: [{ network: "198.51.100.0/24", record }] });
    const got = await withReader(path, async (r) => (await r.lookup("198.51.100.9")).record);
    expect(got).toEqual({
      text: "Grüße, example",
      flag_true: true,
      flag_false: false,
      u16: 65_535,
      u32: 4_294_967_295,
      u64_small: 42,
      u64_big: 18_446_744_073_709_551_615n,
      u128: 340_282_366_920_938_463_463_374_607_431_768_211_455n,
      i32_neg: -12_345,
      i32_pos: 12_345,
      dbl: 51.5,
      flt: 1.5,
      raw: Buffer.from([1, 2, 3, 250]),
      list: ["a", 7, { nested: [true] }],
      long_text: "x".repeat(300),
      longer_text: "y".repeat(70_000),
      zero: 0,
    });
  });

  it.each([
    ["1-byte pointers", { pointerStyle: "min" as const, padding: 0 }],
    ["2-byte pointers (targets past 2048)", { pointerStyle: "min" as const, padding: 4_000 }],
    ["3-byte pointers (targets past 526336)", { pointerStyle: "min" as const, padding: 600_000 }],
    ["4-byte pointers", { pointerStyle: 3 as const, padding: 0 }],
  ])("follows %s to shared strings", async (_label, opts) => {
    const { path, build } = write({ recordSize: 32, networks: NETWORKS, ...opts });
    expect(build.pointers).toBeGreaterThan(20);
    await withReader(path, async (r) => {
      // The later records' keys and repeated values are all pointers to the first record's strings.
      expect((await r.lookup("2001:db8::5")).record).toMatchObject({ prefix_entity: "Example Corp Ltd", as_entity: "Example Transit Inc", allocation_cc: "XA", as: 64499 });
      expect((await r.lookup("198.51.100.200")).record).toMatchObject({ prefix_entity: "Example Hosting LLC", as_entity: "Example Hosting LLC" });
    });
  });

  it("an ip_version 4 database answers IPv4 and refuses IPv6", async () => {
    const { path } = write({ ipVersion: 4, recordSize: 24, networks: NETWORKS.slice(0, 3) });
    await withReader(path, async (r) => {
      expect(await r.lookup("192.0.2.1")).toMatchObject({ prefixLength: 24, record: { as: 64496 } });
      expect(await r.lookup("203.0.113.1")).toMatchObject({ prefixLength: 25 });
      await expect(r.lookup("2001:db8::1")).rejects.toThrow(MmdbError);
    });
  });

  it("keeps a bounded page cache over thousands of lookups", async () => {
    const { path } = write({ networks: NETWORKS, padding: 2_000_000 });
    await withReader(path, async (r) => {
      for (let i = 0; i < 2_000; i += 1) await r.lookup(`192.0.2.${i % 256}`);
      expect((r as unknown as { pages: Map<number, Buffer> }).pages.size).toBeLessThanOrEqual(PAGE_CACHE_PAGES);
    });
  });
});

describe("MmdbReader: asynchronous reads", () => {
  it("a lookup reads nothing synchronously: it returns a pending promise before any file read completes", async () => {
    const { path } = write({ networks: NETWORKS });
    await withReader(path, async (r) => {
      const pages = (r as unknown as { pages: Map<number, Buffer> }).pages;
      pages.clear();
      const p = r.lookup("192.0.2.1");
      expect(pages.size).toBe(0);
      await Promise.resolve();
      expect(pages.size).toBe(0);
      expect((await p).record).toMatchObject({ as: 64496 });
      expect(pages.size).toBeGreaterThan(0);
    });
  });

  it("concurrent lookups share page reads and all answer", async () => {
    const { path } = write({ recordSize: 28, networks: NETWORKS });
    await withReader(path, async (r) => {
      const ips = ["192.0.2.1", "198.51.100.1", "203.0.113.1", "2001:db8::1", "10.0.0.1", "192.0.2.200"];
      const results = await Promise.all(ips.flatMap((ip) => [r.lookup(ip), r.lookup(ip)]));
      expect(results.map((x) => (x.record as { as?: number } | null)?.as ?? null)).toEqual([64496, 64496, 64497, 64497, 64498, 64498, 64499, 64499, null, null, 64496, 64496]);
    });
  });

  it("close() waits for lookups in flight, then refuses new ones with a fixed message", async () => {
    const r = await MmdbReader.open(write({ networks: NETWORKS }).path);
    const inFlight = r.lookup("2001:db8::7");
    const closing = r.close();
    expect(r.closed).toBe(true);
    await expect(r.lookup("192.0.2.1")).rejects.toThrow(/^mmdb: closed$/);
    expect((await inFlight).record).toMatchObject({ as: 64499 });
    await closing;
    await r.close();
  });
});

describe("MmdbReader: refusals and bounds", () => {
  it("refuses a file without metadata, a non-file and unsupported metadata", async () => {
    await expect(MmdbReader.open(write({ networks: NETWORKS, omitMarker: true }).path)).rejects.toThrow(/metadata marker/);
    await expect(MmdbReader.open(join(dir, "missing.mmdb"))).rejects.toThrow(MmdbError);
    await expect(MmdbReader.open(write({ networks: NETWORKS, metadata: { record_size: mmdbType.uint16(20) } }).path)).rejects.toThrow(/record_size/);
    await expect(MmdbReader.open(write({ networks: NETWORKS, metadata: { binary_format_major_version: mmdbType.uint16(3) } }).path)).rejects.toThrow(/binary format/);
    const empty = join(dir, "empty.mmdb");
    writeFileSync(empty, Buffer.alloc(0));
    await expect(MmdbReader.open(empty)).rejects.toThrow(MmdbError);
  });

  it("refuses non-addresses with a fixed message", async () => {
    await withReader(write({ networks: NETWORKS }).path, async (r) => {
      await expect(r.lookup("not an address")).rejects.toThrow(/^mmdb: not an address$/);
    });
  });

  it("refuses metadata that exceeds the decode budget (the file is not opened)", async () => {
    const big = write({ networks: NETWORKS, metadata: { languages: Array.from({ length: DECODE_MAX_VALUES + 10 }, () => "en") } });
    await expect(MmdbReader.open(big.path)).rejects.toThrow(/decode budget/);
  });

  it("pointer amplification: a few KB that would expand to millions of values stops at the budget", async () => {
    // A3 = 200 pointers to A2, A2 = 200 pointers to A1, A1 = 200 pointers to A0, A0 = 200 strings: 8 million values.
    const ARR = 200;
    const head = encodeControl(11, ARR);
    const arrBytes = head.length + ARR * 5;
    const parts: Buffer[] = [];
    for (let level = 0; level < 3; level += 1) parts.push(head, ...Array.from({ length: ARR }, () => encodePointer((level + 1) * arrBytes)));
    parts.push(head, ...Array.from({ length: ARR }, () => Buffer.concat([encodeControl(2, 1), Buffer.from("x")])));
    const blob = Buffer.concat(parts);
    expect(blob.length).toBeLessThan(5_000);
    await withReader(hostile(blob), async (r) => {
      const started = Date.now();
      await expect(r.lookup("192.0.2.1")).rejects.toThrow(/decode budget/);
      expect(Date.now() - started).toBeLessThan(2_000);
    });
  });

  it("a pointer cycle and deep nesting stop at the depth limit", async () => {
    await withReader(hostile(encodePointer(0)), async (r) => {
      await expect(r.lookup("192.0.2.1")).rejects.toThrow(/nested too deeply/);
    });
    const deep = Buffer.concat([...Array.from({ length: DECODE_MAX_DEPTH + 5 }, () => encodeControl(11, 1)), encodeControl(2, 1), Buffer.from("x")]);
    await withReader(hostile(deep), async (r) => {
      await expect(r.lookup("192.0.2.1")).rejects.toThrow(/nested too deeply/);
    });
    const shallow = Buffer.concat([...Array.from({ length: 10 }, () => encodeControl(11, 1)), encodeControl(2, 1), Buffer.from("x")]);
    await withReader(hostile(shallow), async (r) => {
      expect((await r.lookup("192.0.2.1")).record).toEqual([[[[[[[[[["x"]]]]]]]]]]);
    });
  });

  it("strings past the byte budget and fields running past the data section are refused", async () => {
    // Two 600 KB strings in one record: 1.2 MB of text, over the 1 MiB budget.
    const big = write({ networks: [{ network: "192.0.2.0/24", record: { a: "a".repeat(600_000), b: "b".repeat(600_000) } }] });
    await withReader(big.path, async (r) => {
      await expect(r.lookup("192.0.2.1")).rejects.toThrow(/decode budget/);
    });
    // A string that claims 1000 bytes at the end of the data section (truncated data section).
    await withReader(hostile(Buffer.concat([encodeControl(2, 1000), Buffer.from("abc")])), async (r) => {
      await expect(r.lookup("192.0.2.1")).rejects.toThrow(/outside its section/);
    });
  });

  it("a truncated search tree or a record pointer outside the data section is refused", async () => {
    // The metadata claims more nodes than the file holds.
    await expect(MmdbReader.open(write({ networks: NETWORKS, metadata: { node_count: mmdbType.uint32(10_000_000) } }).path)).rejects.toThrow(/search tree/);
    const { path, build } = write({ recordSize: 32, networks: [{ network: "192.0.2.0/24", record: { a: "b" } }] });
    // Corrupt the leaf record that holds 192.0.2.0/24 so it points far past the data section.
    const file = Buffer.from(build.file);
    for (let off = 0; off < build.nodeCount * 8; off += 4) {
      if (file.readUInt32BE(off) > build.nodeCount) file.writeUInt32BE(build.nodeCount + 16 + 10_000_000, off);
    }
    writeFileSync(path, file);
    await withReader(path, async (r) => {
      await expect(r.lookup("192.0.2.1")).rejects.toThrow(/outside the data section/);
    });
  });
});
